export function ExpandableCard({
  title = "{{title}}",
  summary = "{{summary}}",
  details = "{{details}}",
  expanded = {{expanded}},
  color = "{{color}}",
}) {
  return (
    <details open={expanded} style={{ font: "14px system-ui, sans-serif", color: "#241430", border: "1.5px solid " + color, borderRadius: 10, padding: "12px 14px", maxWidth: 300 }}>
      <summary style={{ display: "flex", justifyContent: "space-between", alignItems: "center", cursor: "pointer", listStyle: "none" }}>
        <span>
          <strong style={{ display: "block" }}>{title}</strong>
          <span style={{ display: "block", fontSize: 12, opacity: 0.65 }}>{summary}</span>
        </span>
        <svg viewBox="0 0 12 12" width="12" height="12" aria-hidden="true" style={{ flex: "none", transform: expanded ? "rotate(180deg)" : "none" }}>
          <path d="M2 4l4 4 4-4" fill="none" stroke="#241430" strokeWidth="1.6" />
        </svg>
      </summary>
      <p style={{ margin: "10px 0 0", fontSize: 13, opacity: 0.85 }}>{details}</p>
    </details>
  );
}
